    auto lane=[&](double a,double b){for(int depth=0;;++depth){const auto candidate=a+std::abs(a-b)/2;if(depth>5)return candidate;if(std::ranges::all_of(lanes,[&](double value){return std::abs(value-candidate)>=10;})){lanes.push_back(candidate);return candidate;}b-=std::abs(a-b)/5;}};
    for(std::size_t child=0;child<d.commits.size();++child)for(auto parent:d.commits[child].parents){const auto& a=d.commits[parent];const auto& b=d.commits[child];const auto p=positions[parent],q=positions[child];const auto far=vertical?(p.x<q.x?b.branch:a.branch):(p.y<q.y?b.branch:a.branch);bool reroute=std::ranges::any_of(d.commits,[&](const GitCommit& middle){return middle.seq>a.seq&&middle.seq<b.seq&&middle.branch==far;});auto color_index=branch_color[branch(b)];const bool merge=b.type==GitCommitType::merge&&parent!=b.parents.front();if(merge)color_index=branch_color[branch(a)];std::string path;auto move=[&](char command,Point point){path+=std::string(1,command)+num(point.x)+" "+num(point.y)+" ";bounds.point(point);};auto arc=[&](double radius,int sweep,Point point){path+="A"+num(radius)+" "+num(radius)+" 0 0 "+std::to_string(sweep)+" "+num(point.x)+" "+num(point.y)+" ";bounds.point(point);};move('M',p);
        if(reroute){const auto ly=p.y<q.y?lane(p.y,q.y):lane(q.y,p.y);const auto lx=p.x<q.x?lane(p.x,q.x):lane(q.x,p.x);if(vertical){const auto sign=p.x<q.x?1.0:-1.0,dy=bottom_up?-10.0:10.0;if(sign<0)color_index=branch_color[branch(a)];move('L',{lx-sign*10,p.y});arc(10,(sign>0)!=bottom_up?1:0,{lx,p.y+dy});move('L',{lx,q.y-dy});arc(10,(sign>0)!=bottom_up?0:1,{lx+sign*10,q.y});move('L',q);}else{const auto sign=p.y<q.y?1.0:-1.0;if(sign<0)color_index=branch_color[branch(a)];move('L',{p.x,ly-sign*10});arc(10,sign>0?0:1,{p.x+10,ly});move('L',{q.x-10,ly});arc(10,sign>0?1:0,{q.x,ly+sign*10});move('L',q);}}else if(vertical){if(p.x==q.x)move('L',q);else{const auto sign=p.x<q.x?1.0:-1.0,dy=bottom_up?-20.0:20.0;if(merge){move('L',{p.x,q.y-dy});arc(20,(sign>0)!=bottom_up?0:1,{p.x+sign*20,q.y});move('L',q);}else{move('L',{q.x-sign*20,p.y});arc(20,(sign>0)!=bottom_up?1:0,{q.x,p.y+dy});move('L',q);}}}else if(p.y==q.y)move('L',q);else{const auto sign=p.y<q.y?1.0:-1.0;if(merge){move('L',{q.x-20,p.y});arc(20,sign>0?1:0,{q.x,p.y+sign*20});move('L',q);}else{move('L',{p.x,q.y-sign*20});arc(20,sign>0?0:1,{p.x+20,q.y});move('L',q);}}svg+="<path d=\""+path+"\" class=\"arrow arrow"+std::to_string(color_index)+"\"/>";}
